impl ImsApplicabilityProblem {
    pub const fn code(self) -> &'static str {
        match self {
            Self::UnknownFamily => "IMS1401-001",
            Self::WrongSpelling => "IMS1401-002",
            Self::ForbiddenContext => "IMS1401-003",
            Self::ForbiddenPcbKind => "IMS1401-004",
            Self::ForbiddenOrganization => "IMS1401-005",
            Self::ForbiddenProcessingOption => "IMS1401-006",
            Self::MissingPcbOrOrganization => "IMS1401-007",
            Self::ForbiddenSsaForm => "IMS1401-008",
            Self::UnexpectedPcbOrOrganization => "IMS1401-009",
        }
    }
    pub const fn message(self) -> &'static str {
        match self {
            Self::UnknownFamily => "unknown official IMS call-family row",
            Self::WrongSpelling => "call or command spelling does not belong to this row",
            Self::ForbiddenContext => "call family is not applicable in this execution context",
            Self::ForbiddenPcbKind => "call family requires a different PCB kind",
            Self::ForbiddenOrganization => {
                "call family is not applicable to this database organization"
            }
            Self::ForbiddenProcessingOption => {
                "PCB processing option does not grant this call operation"
            }
            Self::MissingPcbOrOrganization => "call requires a PCB or organization operand",
            Self::ForbiddenSsaForm => "SSA form is not applicable to this call and organization",
            Self::UnexpectedPcbOrOrganization => {
                "call does not accept this PCB or organization operand"
            }
        }
    }
}
